#!/usr/bin/env python3
"""Round 136: THE FEAST, MADE AGAIN — the one effect Kris sent back after the third remake (Lab › Sound effects, sfx_feast: "still need more
options, need a combination of some music and people speaking and mugs clinking"). The round-131 words ended in "no music, no voices" — the
very things he asked for — so these say the opposite: a small folk tune, people talking and laughing (no clear words), mugs and plates.
    python tools/audio/sfx_remake136.py   → sprites/requests/sfx_remake.json (take 'q': audio\\incoming\\sfx_feast.q1.mp3 … q5)
                                           → lab/src/js/79m1h-lab-sfx-remake136.js (the words in the Lab)
Then on the PC: .\\tools\\audio\\audio9.ps1"""
import json, os
R = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
T = ' — a game sound effect that loops, warm and full, music and voices both clearly there but nobody saying words you can make out'
W = {'sfx_feast': ('need a combination of some music and people speaking and mugs clinking', [
    'a Norse feast in a timber longhall: a fiddle and a hand drum playing a merry folk tune, many people talking and laughing over it, wooden mugs knocking together in a toast, plates and cutlery',
    'a village celebration at night: a lively tune on a wooden flute and a frame drum, a crowd chatting warmly, someone laughing loudly, tankards clinking, a hearth fire crackling',
    'a harvest feast: a lute and a drum playing a dancing rhythm, people talking at long tables, clapping along to the music, mugs set down hard on wood, cheerful murmur',
    'a midwinter feast: a jaunty tune on a hurdy-gurdy, a warm hall full of conversation and laughter, horn cups and clay mugs clinking, benches scraping',
    'a joyful gathering: a small folk band (fiddle, whistle, drum) playing, people singing along wordlessly for a moment then talking and laughing, many mugs raised and clinked together'])}
def main():
    S = json.load(open(os.path.join(R, 'sprites', 'requests', 'audio.json'), encoding='utf-8')); C = {c['id']: c for c in S['cues']}
    items = {k: {'why': 'Kris: "' + n + '"', 'meaning': C.get(k, {}).get('name', k) + ' — ' + (C.get(k, {}).get('where') or ''), 'secs': 10, 'words': [w + T for w in ws]} for k, (n, ws) in W.items()}
    J = {'round': 136, 'take': 'q', 'note': 'Round 136: the feast made again with music, voices and mugs (audio\\incoming\\sfx_feast.q1.mp3 … q5).', 'items': items}
    json.dump(J, open(os.path.join(R, 'sprites', 'requests', 'sfx_remake.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    open(os.path.join(R, 'lab', 'src', 'js', '79m1h-lab-sfx-remake136.js'), 'w', encoding='utf-8').write(
        '// round 136: the words for the feast, made again (generated by tools/audio/sfx_remake136.py; made on the PC by tools/audio/audio9.ps1 as sfx_feast.q1 …)\n'
        '(function(){ if(typeof ZAUD==="undefined")return;\n  ZAUD.REMAKE136=' + json.dumps(J, ensure_ascii=False) + ';\n})();\n')
    print(len(items), 'effect,', sum(len(v['words']) for v in items.values()), 'takes')
if __name__ == '__main__': main()
